import re
import sys

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(100000)


class ParseError_(Exception):
    pass


class TypeError_(Exception):
    pass


class RuntimeError_(Exception):
    pass


# --- Lexer ---

TK_EOF = 0
TK_INT = 1
TK_IDENT = 2
TK_TRUE = 3
TK_FALSE = 4
TK_INT_TYPE = 5
TK_BOOL_TYPE = 6
TK_LET = 7
TK_REC = 8
TK_IN = 9
TK_IF = 10
TK_THEN = 11
TK_ELSE = 12
TK_LPAREN = 13
TK_RPAREN = 14
TK_ARROW = 15
TK_SLASH = 16
TK_PLUS = 17
TK_MINUS = 18
TK_STAR = 19
TK_FLOORDIV = 20
TK_MOD = 21
TK_EQEQ = 22
TK_LT = 23
TK_EQ = 24
TK_COLON = 25

_KEYWORDS = {
    "let": TK_LET,
    "rec": TK_REC,
    "in": TK_IN,
    "if": TK_IF,
    "then": TK_THEN,
    "else": TK_ELSE,
}

_RESERVED = frozenset(("match", "with", "type", "forall"))

_UPPER = {
    "True": TK_TRUE,
    "False": TK_FALSE,
    "Int": TK_INT_TYPE,
    "Bool": TK_BOOL_TYPE,
}

_SYM_MAP = {
    "->": TK_ARROW,
    "//": TK_FLOORDIV,
    "==": TK_EQEQ,
    "(": TK_LPAREN,
    ")": TK_RPAREN,
    "/": TK_SLASH,
    "+": TK_PLUS,
    "-": TK_MINUS,
    "*": TK_STAR,
    "%": TK_MOD,
    "<": TK_LT,
    "=": TK_EQ,
    ":": TK_COLON,
}

_TOKEN_RE = re.compile(
    r"(?P<WS>[ \t\n\r\f\v]+)"
    r"|(?P<COMMENT>--[^\n]*)"
    r"|(?P<INT>[0-9]+)"
    r"|(?P<LOWER>[a-z_][A-Za-z0-9_]*)"
    r"|(?P<UPPER>[A-Z][A-Za-z0-9_]*)"
    r"|(?P<SYM>->|//|==|[()/+*%\-=:<])",
    re.ASCII,
)


def tokenize(raw_bytes):
    if not raw_bytes.isascii():
        raise ParseError_("non-ASCII character")
    src = raw_bytes.decode("ascii")
    n = len(src)
    pos = 0
    tokens = []
    match_fn = _TOKEN_RE.match
    while pos < n:
        m = match_fn(src, pos)
        if m is None:
            raise ParseError_(f"unexpected character at {pos}")
        pos = m.end()
        kind = m.lastgroup
        if kind == "WS" or kind == "COMMENT":
            continue
        text = m.group()
        if kind == "INT":
            tokens.append((TK_INT, int(text)))
        elif kind == "LOWER":
            if text == "_" or text in _RESERVED:
                raise ParseError_(f"reserved or invalid identifier: {text}")
            kw = _KEYWORDS.get(text)
            if kw is not None:
                tokens.append((kw, text))
            else:
                tokens.append((TK_IDENT, text))
        elif kind == "UPPER":
            ut = _UPPER.get(text)
            if ut is None:
                raise ParseError_(f"invalid uppercase identifier: {text}")
            tokens.append((ut, text))
        else:
            tokens.append((_SYM_MAP[text], text))
    tokens.append((TK_EOF, None))
    return tokens


# --- Types ---

class TBase:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


T_INT = TBase("Int")
T_BOOL = TBase("Bool")


class TFun:
    __slots__ = ("arg", "ret")

    def __init__(self, arg, ret):
        self.arg = arg
        self.ret = ret


class TVar:
    __slots__ = ("instance",)

    def __init__(self):
        self.instance = None


# --- AST Nodes ---

OP_ADD = 1
OP_SUB = 2
OP_MUL = 3
OP_DIV = 4
OP_MOD = 5
OP_EQ = 6
OP_LT = 7

_BINOP_MAP = {
    TK_PLUS: OP_ADD,
    TK_MINUS: OP_SUB,
    TK_STAR: OP_MUL,
    TK_FLOORDIV: OP_DIV,
    TK_MOD: OP_MOD,
    TK_EQEQ: OP_EQ,
    TK_LT: OP_LT,
}


class AInt:
    __slots__ = ("val",)

    def __init__(self, val):
        self.val = val


class ABool:
    __slots__ = ("val",)

    def __init__(self, val):
        self.val = val


class AVar:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


class ALam:
    __slots__ = ("param", "body")

    def __init__(self, param, body):
        self.param = param
        self.body = body


class AApp:
    __slots__ = ("fn", "arg")

    def __init__(self, fn, arg):
        self.fn = fn
        self.arg = arg


class ABinOp:
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class AIf:
    __slots__ = ("cond", "then_e", "else_e")

    def __init__(self, cond, then_e, else_e):
        self.cond = cond
        self.then_e = then_e
        self.else_e = else_e


class AAnno:
    __slots__ = ("expr", "ty")

    def __init__(self, expr, ty):
        self.expr = expr
        self.ty = ty


class ALet:
    __slots__ = ("name", "ty", "rhs", "body")

    def __init__(self, name, ty, rhs, body):
        self.name = name
        self.ty = ty
        self.rhs = rhs
        self.body = body


class ALetRec:
    __slots__ = ("name", "ty", "rhs", "body")

    def __init__(self, name, ty, rhs, body):
        self.name = name
        self.ty = ty
        self.rhs = rhs
        self.body = body


# --- Parser ---

_ATOM_STARTS = frozenset((TK_IDENT, TK_INT, TK_TRUE, TK_FALSE, TK_LPAREN))


class Parser:
    __slots__ = ("tokens", "pos")

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def expect(self, kind):
        tok_kind, tok_val = self.tokens[self.pos]
        if tok_kind != kind:
            raise ParseError_("unexpected token")
        self.pos += 1
        return tok_val

    def parse_program(self):
        expr = self.parse_expr()
        if self.tokens[self.pos][0] != TK_EOF:
            raise ParseError_("trailing tokens")
        return expr

    def parse_expr(self):
        tk = self.tokens[self.pos][0]
        if tk == TK_SLASH:
            self.pos += 1
            param = self.expect(TK_IDENT)
            self.expect(TK_ARROW)
            body = self.parse_expr()
            return ALam(param, body)
        if tk == TK_LET:
            self.pos += 1
            if self.tokens[self.pos][0] == TK_REC:
                self.pos += 1
                name = self.expect(TK_IDENT)
                self.expect(TK_COLON)
                ty = self.parse_type()
                self.expect(TK_EQ)
                rhs = self.parse_expr()
                if type(rhs) is not ALam:
                    raise ParseError_("let rec RHS must be a lambda")
                self.expect(TK_IN)
                body = self.parse_expr()
                return ALetRec(name, ty, rhs, body)
            name = self.expect(TK_IDENT)
            ty = None
            if self.tokens[self.pos][0] == TK_COLON:
                self.pos += 1
                ty = self.parse_type()
            self.expect(TK_EQ)
            rhs = self.parse_expr()
            self.expect(TK_IN)
            body = self.parse_expr()
            return ALet(name, ty, rhs, body)
        if tk == TK_IF:
            self.pos += 1
            cond = self.parse_expr()
            self.expect(TK_THEN)
            then_e = self.parse_expr()
            self.expect(TK_ELSE)
            else_e = self.parse_expr()
            return AIf(cond, then_e, else_e)
        return self.parse_cmp()

    def parse_cmp(self):
        left = self.parse_add()
        tk = self.tokens[self.pos][0]
        if tk == TK_EQEQ or tk == TK_LT:
            self.pos += 1
            right = self.parse_add()
            return ABinOp(_BINOP_MAP[tk], left, right)
        return left

    def parse_add(self):
        node = self.parse_mul()
        while True:
            tk = self.tokens[self.pos][0]
            if tk == TK_PLUS or tk == TK_MINUS:
                self.pos += 1
                right = self.parse_mul()
                node = ABinOp(_BINOP_MAP[tk], node, right)
            else:
                break
        return node

    def parse_mul(self):
        node = self.parse_app()
        while True:
            tk = self.tokens[self.pos][0]
            if tk == TK_STAR or tk == TK_FLOORDIV or tk == TK_MOD:
                self.pos += 1
                right = self.parse_app()
                node = ABinOp(_BINOP_MAP[tk], node, right)
            else:
                break
        return node

    def parse_app(self):
        node = self.parse_atom()
        while self.tokens[self.pos][0] in _ATOM_STARTS:
            arg = self.parse_atom()
            node = AApp(node, arg)
        return node

    def parse_atom(self):
        tk, val = self.tokens[self.pos]
        if tk == TK_INT:
            self.pos += 1
            return AInt(val)
        if tk == TK_IDENT:
            self.pos += 1
            return AVar(val)
        if tk == TK_TRUE:
            self.pos += 1
            return ABool(True)
        if tk == TK_FALSE:
            self.pos += 1
            return ABool(False)
        if tk == TK_LPAREN:
            self.pos += 1
            expr = self.parse_expr()
            if self.tokens[self.pos][0] == TK_COLON:
                self.pos += 1
                ty = self.parse_type()
                self.expect(TK_RPAREN)
                return AAnno(expr, ty)
            self.expect(TK_RPAREN)
            return expr
        raise ParseError_("expected atom")

    def parse_type(self):
        parts = [self.parse_tatom()]
        while self.tokens[self.pos][0] == TK_ARROW:
            self.pos += 1
            parts.append(self.parse_tatom())
        ty = parts[-1]
        for i in range(len(parts) - 2, -1, -1):
            ty = TFun(parts[i], ty)
        return ty

    def parse_tatom(self):
        tk = self.tokens[self.pos][0]
        if tk == TK_INT_TYPE:
            self.pos += 1
            return T_INT
        if tk == TK_BOOL_TYPE:
            self.pos += 1
            return T_BOOL
        if tk == TK_LPAREN:
            self.pos += 1
            ty = self.parse_type()
            self.expect(TK_RPAREN)
            return ty
        raise ParseError_("expected type")


# --- Typechecker ---

_MISSING = object()


def _prune(t):
    if type(t) is TVar and t.instance is not None:
        root = t
        while type(root) is TVar and root.instance is not None:
            root = root.instance
        cur = t
        while type(cur) is TVar and cur.instance is not None:
            nxt = cur.instance
            cur.instance = root
            cur = nxt
        return root
    return t


def _occurs_in(v, t):
    stack = [t]
    while stack:
        cur = _prune(stack.pop())
        if cur is v:
            return True
        if type(cur) is TFun:
            stack.append(cur.arg)
            stack.append(cur.ret)
    return False


def unify(a, b):
    stack = [(a, b)]
    while stack:
        t1, t2 = stack.pop()
        t1 = _prune(t1)
        t2 = _prune(t2)
        if t1 is t2:
            continue
        if type(t1) is TVar:
            if _occurs_in(t1, t2):
                raise TypeError_("occurs check failed")
            t1.instance = t2
        elif type(t2) is TVar:
            if _occurs_in(t2, t1):
                raise TypeError_("occurs check failed")
            t2.instance = t1
        elif type(t1) is TFun and type(t2) is TFun:
            stack.append((t1.arg, t2.arg))
            stack.append((t1.ret, t2.ret))
        else:
            raise TypeError_("type mismatch")


def infer(node, env):
    nt = type(node)
    if nt is AInt:
        return T_INT
    if nt is ABool:
        return T_BOOL
    if nt is AVar:
        t = env.get(node.name)
        if t is None:
            raise TypeError_(f"unbound variable {node.name}")
        return t
    if nt is ALam:
        tp = TVar()
        old = env.get(node.param, _MISSING)
        env[node.param] = tp
        tb = infer(node.body, env)
        if old is _MISSING:
            del env[node.param]
        else:
            env[node.param] = old
        return TFun(tp, tb)
    if nt is AApp:
        tf = infer(node.fn, env)
        ta = infer(node.arg, env)
        tr = TVar()
        unify(tf, TFun(ta, tr))
        return tr
    if nt is ABinOp:
        tl = infer(node.left, env)
        unify(tl, T_INT)
        tr = infer(node.right, env)
        unify(tr, T_INT)
        if node.op == OP_EQ or node.op == OP_LT:
            return T_BOOL
        return T_INT
    if nt is AIf:
        tc = infer(node.cond, env)
        unify(tc, T_BOOL)
        tt = infer(node.then_e, env)
        te = infer(node.else_e, env)
        unify(tt, te)
        return tt
    if nt is AAnno:
        te = infer(node.expr, env)
        unify(te, node.ty)
        return node.ty
    if nt is ALet:
        trhs = infer(node.rhs, env)
        if node.ty is not None:
            unify(trhs, node.ty)
            tbind = node.ty
        else:
            tbind = trhs
        old = env.get(node.name, _MISSING)
        env[node.name] = tbind
        tbody = infer(node.body, env)
        if old is _MISSING:
            del env[node.name]
        else:
            env[node.name] = old
        return tbody
    if nt is ALetRec:
        old = env.get(node.name, _MISSING)
        env[node.name] = node.ty
        trhs = infer(node.rhs, env)
        unify(trhs, node.ty)
        tbody = infer(node.body, env)
        if old is _MISSING:
            del env[node.name]
        else:
            env[node.name] = old
        return tbody
    raise TypeError_("unknown AST node")


# --- Lowering & Iterative Evaluator ---

class RLam:
    __slots__ = ("param", "body", "fvs")

    def __init__(self, param, body, fvs):
        self.param = param
        self.body = body
        self.fvs = fvs


class RLet:
    __slots__ = ("name", "rhs", "body")

    def __init__(self, name, rhs, body):
        self.name = name
        self.rhs = rhs
        self.body = body


class RLetRec:
    __slots__ = ("name", "param", "fn_body", "fvs", "self_ref", "body")

    def __init__(self, name, param, fn_body, fvs, self_ref, body):
        self.name = name
        self.param = param
        self.fn_body = fn_body
        self.fvs = fvs
        self.self_ref = self_ref
        self.body = body


class Closure:
    __slots__ = ("param", "body", "env")

    def __init__(self, param, body, env):
        self.param = param
        self.body = body
        self.env = env


def lower(node):
    """Returns (runtime_node, free_vars_set)."""
    nt = type(node)
    if nt is AInt or nt is ABool:
        return node, set()
    if nt is AVar:
        return node, {node.name}
    if nt is AAnno:
        return lower(node.expr)
    if nt is ALam:
        rbody, fvs = lower(node.body)
        fvs = fvs - {node.param}
        return RLam(node.param, rbody, tuple(fvs)), fvs
    if nt is AApp:
        rfn, fvs1 = lower(node.fn)
        rarg, fvs2 = lower(node.arg)
        return AApp(rfn, rarg), fvs1 | fvs2
    if nt is ABinOp:
        rl, fvs1 = lower(node.left)
        rr, fvs2 = lower(node.right)
        return ABinOp(node.op, rl, rr), fvs1 | fvs2
    if nt is AIf:
        rc, fvs1 = lower(node.cond)
        rt, fvs2 = lower(node.then_e)
        re_, fvs3 = lower(node.else_e)
        return AIf(rc, rt, re_), fvs1 | fvs2 | fvs3
    if nt is ALet:
        rrhs, fvs1 = lower(node.rhs)
        rbody, fvs2 = lower(node.body)
        return RLet(node.name, rrhs, rbody), fvs1 | (fvs2 - {node.name})
    if nt is ALetRec:
        # node.rhs is guaranteed ALam
        lam = node.rhs
        rfn_body, fn_fvs = lower(lam.body)
        lam_fvs = fn_fvs - {lam.param}
        self_ref = node.name in lam_fvs
        outer_fn_fvs = lam_fvs - {node.name}
        rbody, body_fvs = lower(node.body)
        total_fvs = outer_fn_fvs | (body_fvs - {node.name})
        return (
            RLetRec(
                node.name,
                lam.param,
                rfn_body,
                tuple(outer_fn_fvs),
                self_ref,
                rbody,
            ),
            total_fvs,
        )
    raise RuntimeError("unreachable")


K_LET = 1
K_IF = 2
K_APP_FN = 3
K_APP_ARG = 4
K_BIN_L = 5
K_BIN_R = 6


def evaluate(root):
    expr = root
    env = {}
    stack = []
    push = stack.append
    pop = stack.pop
    mode = 0  # 0 = eval expr, 1 = apply continuation to val
    val = None

    while True:
        if mode == 0:
            nt = type(expr)
            if nt is AVar:
                val = env[expr.name]
                mode = 1
            elif nt is AInt:
                val = expr.val
                mode = 1
            elif nt is ABool:
                val = expr.val
                mode = 1
            elif nt is RLam:
                c_env = {k: env[k] for k in expr.fvs}
                val = Closure(expr.param, expr.body, c_env)
                mode = 1
            elif nt is AApp:
                push((K_APP_FN, expr.arg, env))
                expr = expr.fn
            elif nt is ABinOp:
                push((K_BIN_L, expr.op, expr.right, env))
                expr = expr.left
            elif nt is AIf:
                push((K_IF, expr.then_e, expr.else_e, env))
                expr = expr.cond
            elif nt is RLet:
                push((K_LET, expr.name, expr.body, env))
                expr = expr.rhs
            elif nt is RLetRec:
                c_env = {k: env[k] for k in expr.fvs}
                clos = Closure(expr.param, expr.fn_body, c_env)
                if expr.self_ref:
                    c_env[expr.name] = clos
                env = env.copy()
                env[expr.name] = clos
                expr = expr.body
        else:
            if not stack:
                return val
            frame = pop()
            tag = frame[0]
            if tag == K_APP_FN:
                push((K_APP_ARG, val))
                env = frame[2]
                expr = frame[1]
                mode = 0
            elif tag == K_APP_ARG:
                clos = frame[1]
                env = clos.env.copy()
                env[clos.param] = val
                expr = clos.body
                mode = 0
            elif tag == K_BIN_L:
                push((K_BIN_R, frame[1], val))
                env = frame[3]
                expr = frame[2]
                mode = 0
            elif tag == K_BIN_R:
                op = frame[1]
                lv = frame[2]
                if op == OP_ADD:
                    val = lv + val
                elif op == OP_SUB:
                    val = lv - val
                elif op == OP_MUL:
                    val = lv * val
                elif op == OP_EQ:
                    val = lv == val
                elif op == OP_LT:
                    val = lv < val
                elif op == OP_DIV:
                    if val == 0:
                        raise RuntimeError_("division by zero")
                    val = lv // val
                elif op == OP_MOD:
                    if val == 0:
                        raise RuntimeError_("modulo by zero")
                    val = lv % val
            elif tag == K_IF:
                env = frame[3]
                expr = frame[1] if val else frame[2]
                mode = 0
            elif tag == K_LET:
                env = frame[3].copy()
                env[frame[1]] = val
                expr = frame[2]
                mode = 0


def format_value(val):
    if type(val) is bool:
        return "True" if val else "False"
    if type(val) is int:
        return str(val)
    return "<function>"


def run_file(path):
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError as e:
        sys.stderr.write(f"IO error: {e}\n")
        return 1

    try:
        tokens = tokenize(raw)
        ast = Parser(tokens).parse_program()
    except ParseError_ as e:
        print(f"ParseError: {e}")
        return 1

    try:
        infer(ast, {})
    except TypeError_ as e:
        print(f"TypeError: {e}")
        return 1

    rnode, _ = lower(ast)
    try:
        val = evaluate(rnode)
    except RuntimeError_ as e:
        print(f"RuntimeError: {e}")
        return 1

    print(format_value(val))
    return 0
